/*
 * Узел «Очистка ответа» (n8n-nodes-base.code)
 * Модель deepseek-v4.1-flash:cloud — reasoning-модель: она возвращает в поле
 * output не только ответ клиенту, но и цепочку рассуждений (обычно на английском).
 * Узел оставляет только текст, предназначенный клиенту.
 *
 * 1) Приоритет — служебный маркер «###», с которого агент по системному промпту
 *    начинает ответ клиенту. Маркер ищем ТОЛЬКО в начале строки: если искать
 *    его где угодно, алгоритм спотыкается о собственные рассуждения модели
 *    («the rule says each message starts with ###.») и отдаёт клиенту хвост
 *    цепочки размышлений.
 * 2) Если маркера нет — отбрасываем рассуждения, идя по предложениям с конца
 *    до первого «английского» (нет кириллицы, но больше 12 латинских букв),
 *    и обрезаем сырой текст по началу первого оставленного предложения
 *    (обрезка по индексу, а не склейка, — так сохраняются переводы строк
 *    и список услуг).
 * 3) Дополнительно срезаем англоязычный огрызок в начале ответа
 *    («Let me just ask.\n\nЗдравствуйте! …»).
 */

const raw = String($json.output ?? '').trim();

const hasCyrillic = (s) => /[А-Яа-яЁё]/.test(s);
const latinCount = (s) => (s.match(/[A-Za-z]/g) || []).length;
// Рассуждение: кириллицы нет, а латинских букв много
const isReasoning = (s) => !hasCyrillic(s) && latinCount(s) > 12;

// --- 1. Маркер «###» в начале строки ---------------------------------------
const markerRe = /^[ \t]*###[ \t]*/gm;
const markers = [];
let marker;
while ((marker = markerRe.exec(raw)) !== null) {
	markers.push(marker.index + marker[0].length);
}
for (let i = markers.length - 1; i >= 0; i--) {
	const tail = raw.slice(markers[i]).trim();
	if (hasCyrillic(tail)) {
		return [{ json: { output: tail } }];
	}
}

// --- 2. Без маркера: режем по границе предложения --------------------------
// Режем и там, где пробел после точки потерян («...booking.отово!» — модель
// склеивает рассуждение с ответом).
const parts = raw.split(/(?<=[.!?])(?=\s|[А-Яа-яЁё])/);
const sentences = [];
let cursor = 0;
for (const part of parts) {
	const start = raw.indexOf(part, cursor);
	cursor = start + part.length;
	sentences.push({ start, text: part.trim() });
}

let cut = 0;
for (let i = sentences.length - 1; i >= 0; i--) {
	if (isReasoning(sentences[i].text)) {
		cut = i + 1 < sentences.length ? sentences[i + 1].start : raw.length;
		break;
	}
}

let output = raw.slice(cut).trim();

// --- 3. Англоязычный огрызок в начале ответа -------------------------------
const firstCyrillic = output.search(/[А-Яа-яЁё]/);
if (firstCyrillic > 0 && /[A-Za-z]/.test(output.slice(0, firstCyrillic))) {
	output = output.slice(firstCyrillic).trim();
}

return [{ json: { output: output || raw } }];
